from review import card, save, DATE

i='TCS-3792'; _,c=card(i)
refs=c['references']; refs[0].update(year=2020, locator='OPODIS 2019 proceedings, published 11 February 2020; Section 2 Definitions 1–8, Theorems 19, 29–32, Sections 6–7.')
refs += [dict(id='equivalence',title='On the Number of Objects with Distinct Power and the Linearizability of Set Agreement Objects',authors='David Yu Cheng Chan; Vassos Hadzilacos; Sam Toueg',year=2017,url='https://doi.org/10.4230/LIPIcs.DISC.2017.12',pdf_url='https://drops.dagstuhl.de/storage/00lipics/lipics-vol091-disc2017/LIPIcs.DISC.2017.12/LIPIcs.DISC.2017.12.pdf',locator='Introduction footnote 1 fixes wait freedom; Section 2 defines implementation power; Section 4 defines ports and proves task/object equivalence in Theorem 18.'),dict(id='beyond',title='Life beyond set agreement',authors='David Yu Cheng Chan; Vassos Hadzilacos; Sam Toueg',year=2020,url='https://doi.org/10.1007/s00446-020-00372-5',locator='Distributed Computing 33, 255–277, published 21 April 2020; publisher abstract and model notes checked. Existential separation at each consensus level, not the universal DLSA conjecture.')]
notes=['Recovered the universal n>k>2 non-equivalence conjecture and the wait-free implementation model from the cited DISC 2017 paper.','Defined repeatable operations, movable port access, global agreement, deterministic sequential histories and linearizability.','Distinguished computational equivalence from equality of allowed histories; did not impose obliviousness or a stronger-task proof route.','Separated the proved k=2 cases and the later existential separation from the remaining universal claim.','Corrected the reference publication year while retaining 2019 as the conference-origin year.']
save(i,dict(
 title='Deterministic linearizable objects for set agreement',
 formal='Is it true that, for every pair of integers n>k>2, no deterministic linearizable (n,k)-set agreement object is computationally equivalent to the (n,k)-set agreement task? The quantifier includes every proposal domain I with at least n values and every n-ported object satisfying the definitions below. Equivalence means mutual implementation with atomic read/write registers by deterministic wait-free algorithms. The object may depend on n,k and I, may use the chosen port in determining a response, and may be invoked repeatedly; it is not restricted to one call per port.',
 definitions='The system consists of asynchronous processes with distinct identities communicating through shared objects and atomic read/write registers. A process can crash by stopping permanently. Algorithms must be correct for every schedule and every pattern of such crashes. Wait freedom means each operation or task invocation of a process that continues taking steps completes after finitely many of its own steps, regardless of the speeds or failures of other processes; no fixed complexity bound is requested. Reductions are deterministic: randomization is not available. The one-shot task T(n,k,I) has at most n participating processes, each supplying an input in I and deciding once. Every decision is an input supplied by a participant, at most k distinct values are decided, and every participant that continues taking steps must decide. No sequential ordering constraint is added to these task guarantees. An (n,k)-set agreement object O has ports 1,…,n and an operation ProposeSA(v), v∈I. Each process chooses a port for each call and waits for its response before making another call. Access is well formed if no two pending calls use the same port. Ports are not permanently assigned to process identities; arbitrarily many processes may use the object over its lifetime, but at most n calls may be pending simultaneously. Only well-formed access is required to be implemented. On every such execution, each response is the current call’s proposal or a proposal of a previously invoked call, and across the entire execution at most k distinct values are returned. This agreement bound does not reset after a round or after all processes become idle. All invocations are supported and are wait-free. A finite sequential history S is a sequence of completed triples (port,proposal,response). Determinism requires that for every allowed S, port p and proposal v there is a unique response extending S by a call at p with v; different histories or ports may give different responses. Linearizability requires every concurrent history to admit an ordering of its operations that obeys this sequential specification and preserves real-time precedence: an operation whose response precedes another’s invocation must come first. Incomplete calls may be discarded or assigned responses before ordering them. To implement an object means to produce only its allowed histories, with the required termination, for all well-formed client executions; reproducing every allowed history is unnecessary. O and T are computationally equivalent when copies of O and registers can solve T, and O can be implemented from registers and instances of any correct solver for T. A task instance has n one-shot participant roles; separate instances have independent state, and the implementation must rely only on the task guarantees, not on additional agreement power a particular solver might possess. This is the source’s equivalence to the black-box set agreement task. Any number of fresh instances and registers is allowed; a completed operation uses finitely many steps. The object’s specified initial state is fixed independently of client inputs. O already solves T by one proposal per participant on distinct ports, so the substantive issue is whether a reduction from the task to O can exist.',
 question_type='yes_no',
 answer_criterion='Prove that no such object and reverse wait-free implementation exist for every n>k>2, or refute the statement by giving a pair n>k>2, a proposal domain with at least n values, a deterministic linearizable object and a correct wait-free implementation from the set agreement task and registers. A positive proof need not exhibit a stronger set agreement task: that is an additional conjectured explanation in the source, not a required proof method. Restricting objects to port-independent behavior or proving only some parameter pairs does not establish the universal claim.',
 context_blocks=[dict(title='Tasks and reusable objects specify different behavior',text='Set agreement allows several proposed values to be decided. A linearizable object must additionally behave like an ordered sequence of operations. Computational equivalence asks whether these constraints change implementation power, even though the permitted histories differ.',citation='equivalence'),dict(title='Each property separately is attainable',text='The 2017 paper gives a linearizable object equivalent to the task, but its sequential specification allows nondeterministic choices. The OPODIS paper gives a deterministic equivalent object whose concurrent behavior is not linearizable. Requiring both properties is the remaining issue.',citation='primary'),dict(title='The two-value case provides a separation',text='For n≥4, the source proves that every deterministic linearizable (n,2)-set agreement object can solve two-process consensus with registers, whereas the (n,2) task alone cannot. It also proves the n=3 case for objects whose sequential behavior is independent of the port. These theorems do not cover k>2.',citation='primary'),dict(title='A later existential result has different quantifiers',text='The 2020 journal paper constructs deterministic linearizable objects whose full set agreement power is insufficient to implement them. This demonstrates limitations of classifying objects by agreement tasks, but does not establish the claimed separation for every deterministic linearizable (n,k)-set agreement object.',citation='beyond')],
 why='Tests whether deterministic sequential semantics inevitably add coordination power to reusable set agreement objects, clarifying the relation between one-shot tasks and composable shared-memory abstractions.',
 progress=[dict(date='2017-10-12',text='A linearizable, potentially nondeterministic object equivalent to each set agreement task is established.',citation='equivalence'),dict(date='2020-02-11',text='OPODIS 2019 proceedings establish the n≥4,k=2 deterministic separation and state the n>k>2 conjecture.',citation='primary'),dict(date='2020-04-21',text='The journal treatment of Life beyond set agreement establishes existential gaps between task-solving power and object implementation power; its statement does not resolve the universal conjecture here.',citation='beyond')],
 references=refs,status='open',status_note='Read the OPODIS definitions and conclusion and the cited DISC 2017 implementation model. Checked the publisher’s 2020 Life beyond set agreement abstract and subsequent-work searches through 12 September 2026. No resolution of the universal n>k>2 statement was located. The later paper was checked at the abstract/model-note level, not by a full proof review; searches are not exhaustive.',
 model_self_contained=True,requires_context=False,review_note='Uses the source’s port model and wait-free computational equivalence, not behavioral identity or randomized solvability. The source’s additional conjecture about stronger agreement tasks is context rather than a prescribed solution route.',
 importance=dict(score=c['importance']['score'],method='editorial',reason='A structural question about whether deterministic linearizable abstractions can express exactly the power of set agreement; relevant to classifications of shared-object coordination power. Existing score retained.',assessed_on=DATE),
 working_summary=dict(sentences=['Set agreement lets n processes decide at most k proposed values.','Its task has an equivalent linearizable object and an equivalent deterministic object, but these known objects do not possess both properties.','The conjecture says no object can possess both properties while retaining exactly the task’s implementation power whenever n>k>2.','Equivalence uses deterministic wait-free reductions with registers and allows repeated operations through n ports.','The source proves the analogous separation for k=2 and n≥4; later existential object separations do not settle the universal higher-k question.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','equivalence','beyond'])
),notes=notes,checked_sources=[r['url'] for r in refs])
